from fastapi import APIRouter, Request, HTTPException, Depends

router = APIRouter(prefix="/edge-cache")

@router.get("/sessions/{session_id}/snapshot")
async def get_granian_cached_session(
    session_id: str,
    request: Request,
    current_user: User = Depends(get_authenticated_user)
):
    worker_cache = request.scope.get("granian.worker_cache", {})
    if session_id not in worker_cache:
        raise HTTPException(status_code=404, detail="Session state not found in worker cache")

    session_data = worker_cache[session_id]
    if session_data.get("tenant_id") != current_user.tenant_id:
        raise HTTPException(status_code=403, detail="Forbidden: Unauthorized access to worker cache entry")

    return {"session_id": session_id, "snapshot": session_data}
